import re
import os
import sqlite3
import hashlib
import hmac
import secrets
import time
from functools import lru_cache
from pathlib import Path

DB_PATH = os.environ.get('DB_PATH', '/var/app/data.db')
SECRET_KEY = os.environ.get('SECRET_KEY', secrets.token_hex(32))
UPLOAD_DIR = Path(os.environ.get('UPLOAD_DIR', '/var/app/uploads')).resolve()
REQUEST_TIMEOUT = 5

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute('PRAGMA journal_mode=WAL')
    return conn

def init_db():
    conn = get_db()
    conn.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user'
    )''')
    conn.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY,
        owner_id INTEGER NOT NULL,
        title TEXT NOT NULL,
        content TEXT,
        access_policy TEXT NOT NULL DEFAULT '*',
        FOREIGN KEY (owner_id) REFERENCES users(id)
    )''')
    conn.commit()
    conn.close()

def hash_password(password):
    salt = secrets.token_hex(16)
    h = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 310000)
    return f"{salt}${h.hex()}"

def verify_password(password, stored):
    try:
        salt, hash_hex = stored.split('$', 1)
        h = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 310000)
        return hmac.compare_digest(h.hex(), hash_hex)
    except (ValueError, AttributeError):
        return False

def create_session_token(user_id):
    timestamp = int(time.time())
    payload = f"{user_id}:{timestamp}"
    sig = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{sig}"

def verify_session(token):
    try:
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None
        payload, sig = parts
        expected = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected):
            return None
        user_id_str, ts_str = payload.split(':', 1)
        timestamp = int(ts_str)
        if time.time() - timestamp > 86400:
            return None
        return int(user_id_str)
    except (ValueError, AttributeError):
        return None

# Access policy pattern: matches comma-separated list of user/role specs
# Examples: "*", "user:alice,role:admin", "user:bob,user:charlie,role:editor"
ACCESS_POLICY_PATTERN = re.compile(
    r'^((?:(?:user|role):[a-zA-Z0-9_]+)(?:,(?:(?:user|role):[a-zA-Z0-9_]+))*|\*)$'
)

def _parse_policy_entries(policy_str):
    """Parse access policy string into list of (type, value) tuples."""
    if policy_str == '*':
        return [('wildcard', '*')]
    entries = []
    for entry in policy_str.split(','):
        if ':' in entry:
            etype, evalue = entry.split(':', 1)
            entries.append((etype.strip(), evalue.strip()))
    return entries

def check_document_access(user_id, username, user_role, document_id):
    """Check if user has access to document based on its access_policy field.
    Returns True if access granted, False otherwise."""
    conn = get_db()
    try:
        cursor = conn.execute(
            'SELECT owner_id, access_policy FROM documents WHERE id = ?',
            (document_id,)
        )
        row = cursor.fetchone()
        if row is None:
            return False
        owner_id, policy_str = row
        # Owner always has access
        if owner_id == user_id:
            return True
        # Validate policy format before parsing
        if not ACCESS_POLICY_PATTERN.match(policy_str):
            # Invalid policy format - deny access for safety
            return False
        # Parse and check policy entries
        entries = _parse_policy_entries(policy_str)
        for etype, evalue in entries:
            if etype == 'wildcard':
                return True
            elif etype == 'user' and evalue == username:
                return True
            elif etype == 'role' and evalue == user_role:
                return True
        return False
    finally:
        conn.close()

def get_document(user_id, username, user_role, document_id):
    """Retrieve document if user has access."""
    if not check_document_access(user_id, username, user_role, document_id):
        return {'error': 'Access denied', 'status': 403}
    conn = get_db()
    try:
        cursor = conn.execute(
            'SELECT id, title, content, owner_id FROM documents WHERE id = ?',
            (document_id,)
        )
        row = cursor.fetchone()
        if row is None:
            return {'error': 'Not found', 'status': 404}
        return {'id': row[0], 'title': row[1], 'content': row[2], 'owner_id': row[3], 'status': 200}
    finally:
        conn.close()

def create_document(user_id, title, content, access_policy):
    """Create a new document with specified access policy."""
    # Validate access policy format
    if access_policy != '*':
        if not ACCESS_POLICY_PATTERN.match(access_policy):
            return {'error': 'Invalid access policy format', 'status': 400}
    conn = get_db()
    try:
        cursor = conn.execute(
            'INSERT INTO documents (owner_id, title, content, access_policy) VALUES (?, ?, ?, ?)',
            (user_id, title, content, access_policy)
        )
        conn.commit()
        return {'id': cursor.lastrowid, 'status': 201}
    finally:
        conn.close()

def update_access_policy(user_id, document_id, new_policy):
    """Update document access policy. Only owner can do this."""
    conn = get_db()
    try:
        cursor = conn.execute(
            'SELECT owner_id FROM documents WHERE id = ?', (document_id,)
        )
        row = cursor.fetchone()
        if row is None:
            return {'error': 'Not found', 'status': 404}
        if row[0] != user_id:
            return {'error': 'Only owner can update policy', 'status': 403}
        # Validate new policy before storing
        if new_policy != '*':
            if not ACCESS_POLICY_PATTERN.match(new_policy):
                return {'error': 'Invalid policy format', 'status': 400}
        conn.execute(
            'UPDATE documents SET access_policy = ? WHERE id = ?',
            (new_policy, document_id)
        )
        conn.commit()
        return {'status': 200}
    finally:
        conn.close()

def _is_within_directory(target, base):
    """Safely determine whether target is contained within base."""
    target = Path(target).resolve()
    base = Path(base).resolve()
    try:
        return target.is_relative_to(base)
    except AttributeError:
        # Python < 3.9 fallback
        return base == target or base in target.parents

def upload_file(user_id, filename, data):
    """Upload a file to user's directory."""
    safe_name = Path(filename).name
    if not safe_name or safe_name.startswith('.'):
        return {'error': 'Invalid filename', 'status': 400}
    user_dir = UPLOAD_DIR / str(user_id)
    user_dir.mkdir(parents=True, exist_ok=True)
    target = (user_dir / safe_name).resolve()
    if not _is_within_directory(target, UPLOAD_DIR):
        return {'error': 'Invalid path', 'status': 400}
    target.write_bytes(data)
    return {'path': str(target), 'status': 201}

def register_user(username, password):
    """Register a new user."""
    if not re.match(r'^[a-zA-Z0-9_]{3,32}$', username):
        return {'error': 'Invalid username', 'status': 400}
    if len(password) < 8:
        return {'error': 'Password too short', 'status': 400}
    conn = get_db()
    try:
        pw_hash = hash_password(password)
        conn.execute(
            'INSERT INTO users (username, password_hash, role) VALUES (?, ?, ?)',
            (username, pw_hash, 'user')
        )
        conn.commit()
        return {'status': 201}
    except sqlite3.IntegrityError:
        return {'error': 'Username taken', 'status': 409}
    finally:
        conn.close()

def login(username, password):
    """Authenticate user and return session token."""
    conn = get_db()
    try:
        cursor = conn.execute(
            'SELECT id, password_hash FROM users WHERE username = ?',
            (username,)
        )
        row = cursor.fetchone()
        if row is None:
            verify_password(password, 'dummy$' + '0' * 64)
            return {'error': 'Invalid credentials', 'status': 401}
        if not verify_password(password, row[1]):
            return {'error': 'Invalid credentials', 'status': 401}
        token = create_session_token(row[0])
        return {'token': token, 'status': 200}
    finally:
        conn.close()
